import pathlib,subprocess,json,hashlib,datetime
root=pathlib.Path('products/services/tender-instant-preview')
runs=[]
for name in ['parity.py','ui_test.py','deadline_tests.py']:
 p=root/'tests'/name
 r=subprocess.run(['python3',str(p)],capture_output=True,text=True,timeout=120)
 runs.append({'test':str(p),'returncode':r.returncode,'stdout':r.stdout,'stderr':r.stderr})
files={}
for base in [root,pathlib.Path('products/sites/open-software-tenders'),pathlib.Path('products/services/tender-offer-test/offset-strictness')]:
 for p in sorted(base.rglob('*')):
  if p.is_file() and '__pycache__' not in str(p):
   b=p.read_bytes(); files[str(p)]={'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
inspection={}
for p in sorted(root.rglob('*')):
 if p.is_file() and p.suffix in ['.py','.js','.diff'] and '__pycache__' not in str(p): inspection[str(p)]=p.read_text()
for name in ['index.html','preview.html','llms.txt']:
 p=pathlib.Path('products/sites/open-software-tenders')/name
 if p.exists(): inspection[str(p)]=p.read_text()
result={'observed_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'synthetic_only':True,'execution':'Offline Python and Node; actual browser and customer delivery not established','runs':runs,'files':files,'source_inspection':inspection,'verdict':'Pending independent assessment of executed assertions, baseline restoration and complete preview source; exit codes alone are insufficient'}
out=pathlib.Path('products/reviews/tender-preview-date-executed.json');out.parent.mkdir(parents=True,exist_ok=True);out.write_text(json.dumps(result,ensure_ascii=False,indent=2))
saved=json.loads(out.read_text());print(json.dumps({'runs':saved['runs'],'files':saved['files'],'inspection_files':list(saved['source_inspection']),'verdict':saved['verdict']},ensure_ascii=False,indent=2))
